          <ExternalLink aria-hidden="true" className="ml-0.5 inline h-3 w-3 align-[-1px]" />
          <span className="sr-only"> (öffnet in neuem Fenster)</span>
        </a>
      ) : (
        <span>{titel}</span>
      )}
