// test/hilfen/aufloesen.mjs – Auflöse-Hook zu registrieren.mjs (nur für Tests)
import { existsSync, statSync } from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const WURZEL = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const SRC = path.join(WURZEL, "src");
const klein = (p) => (process.platform === "win32" ? p.toLowerCase() : p);
const imProjekt = (p) => klein(p).startsWith(klein(WURZEL)) && !p.includes(`${path.sep}node_modules${path.sep}`);

function kandidat(basis) {
  for (const p of [basis, `${basis}.js`, `${basis}.mjs`, path.join(basis, "index.js")]) {
    if (existsSync(p) && statSync(p).isFile()) return p;
  }
  return null;
}

export async function resolve(spezifizierer, kontext, weiter) {
  let basis = null;
  if (spezifizierer.startsWith("@/")) basis = path.join(SRC, spezifizierer.slice(2));
  else if ((spezifizierer.startsWith("./") || spezifizierer.startsWith("../")) && kontext.parentURL?.startsWith("file:")) {
    const eltern = fileURLToPath(kontext.parentURL);
    if (imProjekt(eltern)) basis = path.resolve(path.dirname(eltern), spezifizierer);
  }
  if (basis && imProjekt(basis)) {
    const datei = kandidat(basis);
    if (datei && /\.m?js$/.test(datei)) return { url: pathToFileURL(datei).href, shortCircuit: true, format: "module" };
  }
  return weiter(spezifizierer, kontext);
}
// Tests der JSON-LD-Komponente:  node --test src/components/JsonLd.test.mjs
import test from "node:test";
import assert from "node:assert/strict";
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import JsonLd, { jsonLdText } from "./JsonLd.js";

const BOESE = '</script><script>alert(1)</script><!-- & -->';

function inhalt(html) {
  const m = html.match(/^<script type="application\/ld\+json"[^>]*>([\s\S]*)<\/script>$/);
  assert.ok(m, `kein einzelner JSON-LD-Block: ${html}`);
  return m[1];
}

test("</script> im Projekttitel rendert sicher", () => {
  const daten = { "@context": "https://schema.org", "@type": "Product", name: BOESE, description: `Text ${BOESE}` };
  const html = renderToStaticMarkup(createElement(JsonLd, { daten }));
  const roh = inhalt(html);
  // genau ein schließendes </script> (das eigene), kein zweites <script
  assert.equal(html.match(/<\/script/gi).length, 1);
  assert.equal(html.match(/<script/gi).length, 1);
  assert.ok(!/[<>&]/.test(roh), "unescapte <, > oder & im Inhalt");
  assert.ok(!roh.includes("<!--"));
  // Inhalt ist gültiges JSON und ergibt exakt die Originaldaten
  assert.deepEqual(JSON.parse(roh), daten);
});

test("Groß-/Kleinschreibung </SCRIPT> wird ebenfalls neutralisiert", () => {
  const html = renderToStaticMarkup(createElement(JsonLd, { daten: { name: "</SCRIPT ><img src=x onerror=alert(1)>" } }));
  assert.equal(html.match(/<\/script/gi).length, 1);
  assert.equal(JSON.parse(inhalt(html)).name, "</SCRIPT ><img src=x onerror=alert(1)>");
});

