export function fmtFaktWert(fakt, land = fakt?.land) {
  if (!fakt || fakt.wert === null || fakt.wert === undefined) return "–";
  const l = land === "DACH" || !land ? "DE" : land;
  const roh = String(fakt.einheit || "");
