const a=require(process.env.TEMP+'/claims-vorher.json'), b=require(process.env.TEMP+'/claims-nachher.json');
const k=o=>JSON.stringify(Object.keys(o));console.log(k(a));
const f=o=>(o.funde||o.treffer||[]).map(x=>x.datei+'|'+x.regel+'|'+(x.text||x.fund));
